          {financialCoverage && <section className="mb-5 rounded-2xl border border-[#e4d9c4] bg-[#fffaf1] p-5 shadow-[0_5px_18px_rgba(126,91,36,0.06)]"><div className="flex flex-wrap items-start justify-between gap-3"><div><div className="flex items-center gap-2"><div className="flex h-9 w-9 items-center justify-center rounded-xl bg-[#f5e5c6] text-[#a36f2b]"><FileWarning className="h-4 w-4" /></div><div><p className="text-xs font-semibold text-[#8b642d]">اكتمال البيانات المالية</p><p className="mt-1 text-[11px] text-[#927c5b]">الفترة الحالية: {financialCoverage.period}</p></div></div></div><div className="text-left"><p className="text-2xl font-bold text-[#7d5724]">{financialCoverage.rate === null ? "—" : `${financialCoverage.rate}%`}</p><p className="text-[10px] text-[#927c5b]">{financialCoverage.centersWithData} من {financialCoverage.expectedCenters} مركزًا ماليًا</p></div></div><div className="mt-4 h-2 overflow-hidden rounded-full bg-[#f0e4cf]"><div className={`h-full rounded-full ${financialCoverage.rate === 100 ? "bg-[#4d9168]" : "bg-[#c48635]"}`} style={{ width: `${Math.min(100, Math.max(0, financialCoverage.rate ?? 0))}%` }} /></div>{financialCoverage.missingCenters.length > 0 ? <div className="mt-4"><p className="text-[11px] font-semibold text-[#7d5724]">مراكز تحتاج إدخال أو مراجعة بيانات {financialCoverage.period}</p><div className="mt-2 flex flex-wrap gap-2">{financialCoverage.missingCenters.slice(0, 8).map((center) => <button key={center.id} type="button" className="rounded-full border border-[#e6cda5] bg-white px-3 py-1.5 text-[10px] font-semibold text-[#855f2a] hover:bg-[#fff4df]" onClick={() => { const branch = displayBranches.find((item) => item.id === center.id); if (branch) setSelectedBranch(branch); }}>{center.name}</button>)}{financialCoverage.missingCenters.length > 8 && <span className="rounded-full bg-[#f5e8d0] px-3 py-1.5 text-[10px] text-[#8f744b]">+{financialCoverage.missingCenters.length - 8} مراكز أخرى</span>}</div></div> : <p className="mt-4 text-[11px] font-semibold text-[#4d7d5e]">اكتملت بيانات جميع المراكز المالية المتوقعة لهذه الفترة.</p>}</section>}
          <section className="mb-3 flex flex-wrap items-center justify-between gap-3 rounded-2xl border border-border bg-card p-3 text-card-foreground shadow-sm print:hidden"><div><p className="text-sm font-bold">أدوات لوحة المدير</p><p className="mt-1 text-[11px] text-muted-foreground">تصدير المؤشرات والاتجاهات الحالية مباشرة للاجتماعات والمراجعة.</p></div><ExecutiveDashboardExport data={executiveOps} disabled={executiveFetching} userKey={user?.openId ?? user?.id ?? null} /></section>
